package com.ghosttap.core

/**
 * The demo test card: the recorded tap conversation and the values the
 * lab's simulation proved against it. Test data only — a made-up card
 * that can never pay anywhere.
 *
 * This file holds data and nothing else: no flow, no checks. The
 * engine in EmvEngine.kt runs this data through the exact same steps
 * as a real tapped card, one command at a time, in the recorded order.
 */
object EmvDemoCard {

    /**
     * The 5 recorded steps from the known-good tap conversation
     * (test Visa card, PAN 1234560012345608, expiry 291231):
     * SELECT PPSE, SELECT AID, GET PROCESSING OPTIONS, READ RECORD 1,
     * READ RECORD 2. Each pair is (command sent, answer received),
     * full answers including the trailing 90 00.
     */
    val exchanges: List<Pair<ByteArray, ByteArray>> = listOf(
        // 1. SELECT PPSE (2PAY.SYS.DDF01)
        ("00A404000E325041592E5359532E444446303100".hexToBytes() ?: byteArrayOf()) to
            ("6F36840E325041592E5359532E4444463031A524BF0C21611F4F07AFFFFFFFFF1234500D5645534120454C454354524F4E8701019F2A01039000".hexToBytes() ?: byteArrayOf()),
        // 2. SELECT AID (AF FF FF FF FF 12 34, test Visa)
        ("00A4040007AFFFFFFFFF123400".hexToBytes() ?: byteArrayOf()) to
            ("6F548407AFFFFFFFFF1234A549500D5645534120454C454354524F4E5F2D02656E8701019F1210564553412020202020202020202020209F1101019F38189F66049F02069F03069F1A0295055F2A029A039C019F37049000".hexToBytes() ?: byteArrayOf()),
        // 3. GET PROCESSING OPTIONS
        ("80A8000023832136004000000000000100000000000000024600000000000978261004001234567800".hexToBytes() ?: byteArrayOf()) to
            ("".hexToBytes() ?: byteArrayOf()),
        // 4. READ RECORD SFI 3 record 1
        ("00B2011C00".hexToBytes() ?: byteArrayOf()) to
            ("70505F24032912315A0812345600123456085F3401019F0702FF808E1400000000000000000201440341031E0302031F009F0D05B8483C98009F0E0500108000009F0F05B8483C98005F280202469F4A01829000".hexToBytes() ?: byteArrayOf()),
        // 5. READ RECORD SFI 3 record 2
        ("00B2021C00".hexToBytes() ?: byteArrayOf()) to
            ("703E9F420209789F4401029F080200968C159F02069F03069F1A0295055F2A029A039C019F37048D178A029F02069F03069F1A0295055F2A029A039C019F37049000".hexToBytes() ?: byteArrayOf())
    )

    /** Demo terminal values — the exact bytes the recorded GPO sends. */
    const val AMOUNT_HEX = "000000000100"
    const val CURRENCY_HEX = "0978"
    const val COUNTRY_HEX = "0246"
    const val DATE_HEX = "261004"
    const val TYPE_HEX = "00"
    const val UNPREDICTABLE_HEX = "12345678"
    const val TTQ_HEX = "36004000"

    /** The 0200 the lab built from this tap — the engine must match it. */
    const val EXPECTED_0200_HEX =
        ""

    /** The test host's answer to that 0200: approved, test data only. */
    const val TEST_0210_APPROVED = true
    const val TEST_0210_AUTH_CODE = "123456"
    const val TEST_0210_RRN = "100410000001"
    const val TEST_0210_DE7 = "1004100000"
}
